    public static String evaluate(String s, List<List<String>> knowledge) {
        StringBuilder ret = new StringBuilder();
        int openIndex = 0;
        int closeIndex = 0;
        boolean isKnowledge = false;
        for(int i=0;i<s.length();i++){
            if(s.charAt(i) == '('){
                openIndex = i;
            } else if (s.charAt(i) == ')'){
                ret.append( s, closeIndex, openIndex );
                closeIndex = i;
                isKnowledge = false;
                for ( List<String> strings : knowledge ) {
                    if ( strings.getFirst().equals( s.substring( openIndex + 1, i ) ) ) {
                        ret.append( strings.get( 1 ) );
                        isKnowledge = true;
                        break;
                    }
                }
                if(!isKnowledge){
                    ret.append( "?" );
                }
                closeIndex++;
            }
        }

        ret.append( s.substring( closeIndex ) );
        return ret.toString();
    }
